# Chapter 1: Burland and Izmit, the places between them and the overworld around them.
# Which Super Famicom square takes the place of which NES square (tools/sfc/pack.py reads this).
# The place keeps its own character: the grey brick and the colors the NES game gave it come first, and the art
# is chosen to fit them. Every wall (the castle inside and out, the towns' buildings) is Dragon Quest I's castle
# brick; the ground, the plants, the water, the furniture, the people and the overworld are Dragon Quest III's,
# toned where it has the right thing only in another place's colors (its tan castle's round towers, gate and
# braziers stand in the brick's grey on the castle's front; its olive bushes are green here).
# The first line for a square stays. A line with "here" is for the kind of map its NES square was listed in (the
# game's number at $28: one NES square is a town's road, a castle's floor and a house's floor) and is looked up
# before the lines for any kind. A thing laid over "=town:3E51A0A88427F85B" stands on the floor the place itself has
# (that square is a town's road, a castle's floor and a room's floor).

lib dq3t ../../../generated/sfc/dq3_town.sfclib
lib dq3c ../../../generated/sfc/dq3_castle.sfclib
lib dq3f ../../../generated/sfc/dq3_front.sfclib
lib dq3h ../../../generated/sfc/dq3_house.sfclib
lib dq3v ../../../generated/sfc/dq3_cave.sfclib
lib dq3w ../../../generated/sfc/dq3_tower.sfclib
figs dq3 ../../../generated/sfc/dq3.figs
lib dq1 ../../../generated/sfc/dq1_castle.sfclib
lib dq1ow ../../../generated/sfc/dq1_ow.sfclib
lib dq3ow ../../../generated/sfc/dq3_ow.sfclib
figs dq1 ../../../generated/sfc/dq1.figs
figs dq3p ../../../generated/sfc/dq3_party.figs
figs dq3n ../../../generated/sfc/dq3_people.figs
figs dq6n ../../../generated/sfc/dq6_people.figs   # Dragon Quest VI's people, drawn by the game by number (extract.py: DQ6_PEOPLE)
nes castle ../../../generated/sfc/nes_castle.json
nes town ../../../generated/sfc/nes_town.json
nes ow ../../../generated/sfc/nes_overworld.json
people people ../../../generated/sfc/nes_people.json
# what the "Graphical Uncensoring" hack changes in these maps (the church's sign and its priest get their crosses back)
nes uncensored ../../../generated/sfc/nes_uncensored.json
people uncensored ../../../generated/sfc/nes_people_uncensored.json
# Burland's castle, the upper floor (kind $09); rooms upstairs in Burland and Izmit ($03); Izmit ($0E)
nes castle_up ../../../generated/sfc/nes_castle_up.json
nes rooms ../../../generated/sfc/nes_rooms.json
nes izmit ../../../generated/sfc/nes_izmit.json
# the cave between Burland and Izmit ($1D); the old well ($2A); the tower ($2B, its top floors $26)
nes tunnel ../../../generated/sfc/nes_tunnel.json
nes well ../../../generated/sfc/nes_well.json
nes tower ../../../generated/sfc/nes_tower.json
nes tower_top ../../../generated/sfc/nes_tower_top.json
people ch1 ../../../generated/sfc/nes_people_ch1.json

